from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for integers a >= 1, b >= 2."""
    # Every square is represented by its root; add higher powers that are not squares.
    count = isqrt(n)
    nonsquare_powers = set()

    # Any power with exponent >= 3 has a base at most floor(cuberoot(n)).
    # Multiplying repeatedly avoids floating-point root rounding errors.
    for a in range(2, 1_000_001):
        value = a * a * a
        if value > n:
            break
        while value <= n:
            root = isqrt(value)
            if root * root != value:
                nonsquare_powers.add(value)
            value *= a

    return count + len(nonsquare_powers)

