from typing import List, Tuple
from functools import lru_cache


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the grid can be tiled by a subset of the available rectangles.

    Tiles may be rotated, must align with cells, and may not overlap or leave the grid.
    """
    tiles = tiles[:n]
    target = h * w
    areas = [a * b for a, b in tiles]
    if sum(areas) < target:
        return False
    # A complete tiling must use some subset whose areas sum to the grid area.
    possible = {0}
    for area in areas:
        possible |= {x + area for x in tuple(possible)}
    if target not in possible:
        return False

    full = (1 << target) - 1

    @lru_cache(None)
    def search(mask: int, used: int) -> bool:
        if mask == full:
            return True
        # Find the first uncovered cell in row-major order.
        remaining = full ^ mask
        bit = remaining & -remaining
        pos = bit.bit_length() - 1
        row, col = divmod(pos, w)
        for i, (a, b) in enumerate(tiles):
            if used >> i & 1:
                continue
            for height, width in {(a, b), (b, a)}:
                if row + height > h or col + width > w:
                    continue
                rect = ((1 << width) - 1) << pos
                for rr in range(1, height):
                    rect |= ((1 << width) - 1) << (pos + rr * w)
                if mask & rect == 0 and search(mask | rect, used | (1 << i)):
                    return True
        return False

    return search(0, 0)

