def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful numbers in [l, r], inclusive.

    A positive integer is beautiful when the product of its digits is divisible
    by the sum of its digits.
    """
    def count_leq(n: int) -> int:
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        total = 0
        for target in range(1, 9 * len(digits) + 1):
            # State: (digit sum, product modulo target, started, tight).
            states = {(0, 1 % target, False, True): 1}
            for bound_digit in digits:
                next_states = {}
                for (digit_sum, remainder, started, tight), ways in states.items():
                    ceiling = bound_digit if tight else 9
                    for digit in range(ceiling + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target:
                            continue
                        new_started = started or digit != 0
                        if not new_started:
                            new_remainder = remainder
                        elif started:
                            new_remainder = remainder * digit % target
                        else:
                            new_remainder = digit % target
                        key = (new_sum, new_remainder, new_started,
                               tight and digit == bound_digit)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states
            total += sum(
                ways for (digit_sum, remainder, started, _), ways in states.items()
                if started and digit_sum == target and remainder == 0
            )
        return total

    return count_leq(r) - count_leq(l - 1)

