from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the least cost of covering each section within the sensor limits."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    if l1 <= 0 or l2 <= 0 or c1 < 0 or c2 < 0:
        return -1

    # States are (number of type-1 sensors, number of type-2 sensors) -> cost.
    states = {(0, 0): 0}
    for d in sections[:n]:
        options = []
        max_x = min(k1, (d + l1 - 1) // l1)
        for x in range(max_x + 1):
            y = max(0, (d - x * l1 + l2 - 1) // l2)
            if y <= k2:
                options.append((x, y, x * c1 + y * c2))
        if not options:
            return -1

        combined = {}
        for (used_x, used_y), cost in states.items():
            for x, y, extra in options:
                nx, ny = used_x + x, used_y + y
                if nx <= k1 and ny <= k2:
                    value = cost + extra
                    key = (nx, ny)
                    if value < combined.get(key, float("inf")):
                        combined[key] = value
        if not combined:
            return -1

        # Remove states that use at least as many of both sensors and cost
        # no less than another state.
        ordered = sorted((x, y, cost) for (x, y), cost in combined.items())
        ys = sorted({y for _, y, _ in ordered})
        tree = [float("inf")] * (len(ys) + 1)

        def query(i):
            best = float("inf")
            while i:
                best = min(best, tree[i])
                i -= i & -i
            return best

        def update(i, value):
            while i < len(tree):
                if value < tree[i]:
                    tree[i] = value
                i += i & -i

        kept = {}
        for x, y, cost in ordered:
            yi = __import__("bisect").bisect_left(ys, y) + 1
            if query(yi) <= cost:
                continue
            kept[(x, y)] = cost
            update(yi, cost)
        states = kept

    return min(states.values()) if states else -1

