MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo MOD."""
    fact = [1] * (2 * n + 1)
    for i in range(1, len(fact)):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[-1] = pow(fact[-1], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(x: int, y: int) -> int:
        if y < 0 or y > x or x < 0:
            return 0
        return fact[x] * invfact[y] % MOD * invfact[x - y] % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1
        if remaining:
            lo = max(1, slots - 1)
            hi = min(remaining, slots + bound - 2)
            inv_remaining = pow(remaining, MOD - 2, MOD)
            for t in range(lo, hi + 1):
                ways = t * choose(2 * remaining - t - 1, remaining - 1)
                answer = (answer + ways * inv_remaining) % MOD
        elif slots == 1 and bound > 0:
            answer = (answer + 1) % MOD

        slots += bound - 1
        if slots <= 0:
            if slots == 0 and i == n - 1:
                answer = (answer + 1) % MOD
            return answer
        if slots > remaining:
            return answer

    return answer

