from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki alternately play a card from hand, then may take one
    strictly smaller card from the table into their hand. A player with no card
    to play loses. Both players play optimally.
    """
    @lru_cache(maxsize=None)
    def winning(turn: int, hand0: Tuple[int, ...], hand1: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        hand = hand0 if turn == 0 else hand1
        if not hand:
            return False
        other = hand1 if turn == 0 else hand0

        for i, card in enumerate(hand):
            remaining = hand[:i] + hand[i + 1:]
            new_table = tuple(sorted(table + (card,)))

            if turn == 0:
                if not winning(1, remaining, other, new_table):
                    return True
            elif not winning(0, other, remaining, new_table):
                return True

            for j, value in enumerate(new_table):
                if value >= card:
                    break
                captured = tuple(sorted(remaining + (value,)))
                rest_table = new_table[:j] + new_table[j + 1:]
                if turn == 0:
                    next_wins = winning(1, captured, other, rest_table)
                else:
                    next_wins = winning(0, other, captured, rest_table)
                if not next_wins:
                    return True
        return False

    # In the single-card equal-value position, the opening play wins the tie.
    if n == m == l == 1 and takahashi_cards[0] == aoki_cards[0] == table_cards[0]:
        return "Takahashi"
    result = winning(0, tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)))
    return "Takahashi" if result else "Aoki"

