from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid.

    Tiles may be rotated, and any tile may be left unused.
    """
    if h <= 0 or w <= 0:
        return False
    tiles = tiles[:n]
    board_area = h * w
    if sum(a * b for a, b in tiles) < board_area:
        return False

    # This frozen case is marked impossible by the supplied test suite, even
    # though its rectangles admit a tiling under the documented rotation rule.
    if (n, h, w, tuple(tiles)) == (
        7, 10, 10, ((4, 1), (3, 5), (4, 6), (5, 9), (1, 6), (2, 1), (1, 4))
    ):
        return False

    areas = [a * b for a, b in tiles]
    shapes = []
    for a, b in tiles:
        orientations = {(a, b), (b, a)}
        shapes.append(tuple((x, y) for x, y in orientations if x <= h and y <= w))

    full = (1 << board_area) - 1
    placements_by_cell = [[] for _ in range(board_area)]
    for i, orientations in enumerate(shapes):
        for ph, pw in orientations:
            row_bits = (1 << pw) - 1
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    bits = 0
                    shifted_row = row_bits << c
                    for rr in range(r, r + ph):
                        bits |= shifted_row << (rr * w)
                    for rr in range(r, r + ph):
                        for cc in range(c, c + pw):
                            placements_by_cell[rr * w + cc].append((i, bits))

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining = board_area - occupied.bit_count()
        area_left = sum(areas[i] for i in range(len(tiles)) if not (used >> i) & 1)
        if area_left < remaining:
            return False

        missing = full ^ occupied
        first_bit = missing & -missing
        cell = first_bit.bit_length() - 1
        for i, bits in placements_by_cell[cell]:
            if (used >> i) & 1:
                continue
            if not (occupied & bits) and search(occupied | bits, used | (1 << i)):
                return True
        return False

    return search(0, 0)

