def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n < 1:
        return 0

    # Mobius values up through the largest possible exponent.
    limit = n.bit_length()
    mobius = [1] * (limit + 1)
    primes = []
    composite = [False] * (limit + 1)
    for i in range(2, limit + 1):
        if not composite[i]:
            primes.append(i)
            mobius[i] = -1
        for p in primes:
            v = i * p
            if v > limit:
                break
            composite[v] = True
            if i % p == 0:
                mobius[v] = 0
                break
            mobius[v] = -mobius[i]

    def power_leq(base: int, exponent: int, bound: int) -> bool:
        # Exponentiation with early cutoff avoids constructing huge integers.
        value = 1
        for _ in range(exponent):
            value *= base
            if value > bound:
                return False
        return True

    def floor_root(value: int, exponent: int) -> int:
        if exponent == 1:
            return value
        lo, hi = 1, 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if power_leq(mid, exponent, value):
                lo = mid
            else:
                hi = mid - 1
        return lo

    def primitive_count(bound: int) -> int:
        # Count integers in [2, bound] whose prime-factor exponents have gcd 1.
        total = 0
        for d in range(1, bound.bit_length() + 1):
            if d > limit:
                break
            if mobius[d]:
                total += mobius[d] * (floor_root(bound, d) - 1)
        return total

    result = 1  # 1 = 1^b for every b >= 2.
    for exponent in range(2, n.bit_length() + 1):
        root = floor_root(n, exponent)
        if root < 2:
            break
        result += primitive_count(root)
    return result

