def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A positive integer N is a 400 number iff it has exactly two distinct
    prime factors, each with an even exponent. Equivalently, N = m**2 where
    m has exactly two distinct prime factors.
    """
    from bisect import bisect_right
    from math import isqrt

    limit = isqrt(a)
    distinct = [0] * (limit + 1)
    for p in range(2, limit + 1):
        if distinct[p] == 0:
            for multiple in range(p, limit + 1, p):
                distinct[multiple] += 1

    best = 0
    for root in range(2, limit + 1):
        if distinct[root] == 2:
            value = root * root
            if value > best:
                best = value
    return best

