        available = full_mask ^ mask
        while available:
            bit = available & -available
            available -= bit
            index = bit.bit_length() - 1
            new_mask = mask | bit

            if takahashi_turn:
                new_takahashi_mask = takahashi_mask | bit
                new_diff = score_diff + values[index]
                if any((new_takahashi_mask & line) == line for line in line_masks):
                    return True
                if play(new_mask, new_takahashi_mask, new_diff):
                    return True
            else:
                new_takahashi_mask = takahashi_mask
                new_diff = score_diff - values[index]
                aoki_mask = new_mask ^ new_takahashi_mask
                if any((aoki_mask & line) == line for line in line_masks):
                    return False
                if not play(new_mask, new_takahashi_mask, new_diff):
                    return False

        return not takahashi_turn

