from typing import List


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count strings of length 1..K with per-letter occurrence limits, modulo 998244353."""
    mod = 998244353
    if not any(C):
        return 1

    fact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact = [1] * (K + 1)
    inv_fact[K] = pow(fact[K], mod - 2, mod)
    for i in range(K, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod

    # Exponential generating function: coefficient of x^j for a letter
    # is 1/j!, since choosing its j positions contributes n!/j!.
    dp = [1] + [0] * K
    for cap in C:
        cap = min(cap, K)
        nxt = [0] * (K + 1)
        for used, ways in enumerate(dp):
            if ways:
                upto = min(cap, K - used)
                for j in range(upto + 1):
                    nxt[used + j] += ways * inv_fact[j]
        dp = [value % mod for value in nxt]

    return sum(dp[n] * fact[n] for n in range(1, K + 1)) % mod

