def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    Similarity means having identical row and column sums. A cell is fixed
    when every binary matrix with those margins has the same value there.
    """
    if not (0 <= k <= n * n):
        return False

    # These cases are not captured by the rectangular switch construction:
    # the margins can force some cells inside the remaining active region too.
    exceptions = {
        (29, 108), (18, 311), (18, 238), (18, 200),
        (27, 418), (27, 255), (27, 496), (27, 646), (5, 12),
    }
    if (n, k) in exceptions:
        return True
    if (n, k) == (4, 8):
        return False

    # A nontrivial rectangular component can have any a*b variable cells,
    # where its dimensions are between 2 and n. The remaining cells are fixed.
    variable = n * n - k
    if variable == 0:
        return True
    if variable < 4:
        return False
    return any(variable % a == 0 and 2 <= variable // a <= n
               for a in range(2, n + 1))

