from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and max product <= limit."""
    # (alternating sum, next sign, nonempty) -> attainable products.
    states = {(0, 1, False): {1}}
    for value in nums:
        updated = {state: products.copy() for state, products in states.items()}
        for (total, sign, _nonempty), products in states.items():
            new_total = total + sign * value
            destination = updated.setdefault((new_total, -sign, True), set())
            if value == 0:
                destination.add(0)
            else:
                for product in products:
                    candidate = product * value
                    if candidate <= limit:
                        destination.add(candidate)
        states = updated

    answer = -1
    for (total, _sign, nonempty), products in states.items():
        if nonempty and total == k and products:
            answer = max(answer, max(products))
    return answer

